figures.script:
diagram("direction: right
[Push] as a
[Lint + test] as b
[Build image] as c
[Staging] as d
[Production] as e
a -> b
b -> c
c -> d
d -> e
@0 a -> b
@1 b -> c
@2 c -> d
@3 d -> e
loop 2");

diagram("mode: sequence
[Users] as u
[Load balancer] as l
[Old v1] as o
[New v2] as n
u -> l : requests
l -> o : 95% of traffic
l -> n : 5% canary
n --> l : errors low
l -> n : raise to 100%
@0 u -> l : requests
@1 l -> o : 95% of traffic
@2 l -> n : 5% canary
@3 n -> l : errors low
@4 l -> n : raise to 100%");
